"""User-facing explanations of every persisted SNR control."""
import json

# key, user label, what it enables, effect of changing it. No profitability claims.
ACTION_GUIDE = (
('breaker_pair_mode','Modo Breaker Pair','Añade la unión de dos velas H1 cerradas del mismo color, incluso sin gap.','Observación mide sin órdenes; Operar admite su primer retest. Mantiene ADX, invalidación, distancia y espacio mínimo de 2R. Es una interpretación pendiente de validación.'),
('breaker_pair_min_body_ratio','Cuerpo de ambas velas Breaker Pair','Exige esta proporción de cuerpo a las dos velas de formación.','Bajarlo admite pares menos definidos; no equivale a un aumento de WinRate.'),
('breaker_pair_min_displacement_atr','Desplazamiento Breaker Pair','Exige que el segundo cierre se aleje de la unión en ATR H1.','Subirlo elimina pares sin impulso. Bajar permite más niveles y más ruido.'),
('retest_pinbar_mode','Modo rechazo Pinbar','Añade barrido real y recuperación con mecha de rechazo larga y cierre direccional.','Observación conserva la confirmación habitual y registra la alternativa por separado. Operar puede confirmar antes; no permite un segundo retest ni rescata niveles invalidados.'),
('retest_pinbar_min_wick_ratio','Mecha mínima Pinbar','Exige una proporción mínima de mecha del lado rechazado respecto al rango.','55% exige rechazo dominante. Sigue necesitando cuerpo direccional, cierre recuperado y penetración limitada.'),
('retest_pinbar_min_close_ratio','Posición mínima del cierre Pinbar','Exige cerrar en la parte favorable del rango, medida según BUY o SELL.','75% exige cierre en el cuarto favorable. Una visita previa sigue exigiendo cuerpo y desplazamiento reforzados.'),
('session_policy','Horario por mercado','Permite horario UTC anterior o ventanas locales Londres 07–11 y Nueva York 07–12, con cambios de hora.','Horario por mercado permite cripto 24/7; sintéticos ya operan sin killzone. No fabrica datos de mercados cerrados ni habilita activos fuera de selección.'),
('obstacle_av_definition','Definición de obstáculos A/V','Permite detectar obstáculos H1 y D1 por envolvente o por giro de cuerpos.','Giro de cuerpos incluye niveles enseñados sin envolvente. Puede reducir entradas con poco recorrido; protege el objetivo mínimo de 2R.'),
('h4_obstacle_mode','Obstáculos H4','Registra o aplica niveles contrarios H4 además de los obstáculos H1 y D1.','Observación añade evidencia sin veto. Operar limita objetivos y bloquea si falta H4 útil o hay un obstáculo antes de 2R; no permite más entradas por sí solo.'),
('step_min_adx','ADX de ejecución Step para SNR','Define el mínimo del filtro adicional del motor, solo para Step del perfil Malaysian SNR.','Es distinto del ADX de formación de Continuación. Bajarlo admite señales antes bloqueadas; 25 es la referencia. No altera otros motores. El ADX puede venir de H1 en la señal SNR.'),
('step_symbol_min_adx','ADX de ejecución por Step','Sobrescribe el mínimo Step para un instrumento; vacío hereda el mínimo general.','Permite ensayar 23 en Step estándar conservando 25 en los demás. Cada excepción cambia la población de señales y requiere nueva validación.'),
('enable_synthetic_daily_storyline_filter','Dirección D1 en sintéticos','Activa el veto direccional D1 para sintéticos. No elimina obstáculos D1 ni la dirección permitida de Boom/Crash.','Desactivarlo admite operaciones contrarias a ese sesgo; activarlo reduce el universo de entradas. Medir el resultado por familia.'),
('fractal_min_body_ratio','Cuerpo Fractal H1','Exige una proporción mínima de cuerpo en la vela H1 del Fractal.','Bajarlo admite velas menos decisivas. Subirlo filtra más patrones; no implica mayor WinRate automáticamente.'),
('fractal_max_entry_distance_atr','Distancia Fractal','Limita cuánto puede separarse la entrada del nivel, en ATR H1.','Ampliarla admite entradas más alejadas y cambia el riesgo y el espacio hasta objetivos; se verifica también al enviar la orden.'),
('retest_window_minutes','Ventana de retest','Mantiene vivo el setup durante esta cantidad de minutos después de su ruptura.','Ampliarla permite retornos más tardíos, pero no revive niveles invalidados, consumidos o ya retesteados.'),
('additional_symbols','Selección adicional histórica','Añade los Jump y Volatility 1s elegidos al escaneo habitual.','Solo actúa si su modo adicional está habilitado. Un modo propio por activo tiene prioridad.'),
('additional_symbols_mode','Modo adicional histórico','Desactivado excluye; Observación registra; Operar permite evaluar órdenes para esa lista.','Una lista vacía no añade activos aunque figure Operar. Operar no sustituye los filtros de entrada.'),
('continuation_mode','Modo Continuación','Habilita rupturas de niveles H1 seguidas de primer retest.','Operar permite entradas de este escenario; Observación mide sin órdenes; Desactivado retira el escenario. El modo del activo tiene prioridad.'),
('continuation_max_entry_distance_atr','Distancia Continuación / A/V','Separa la tolerancia de entrada de Continuación de la del Fractal y QM.','Ampliarla puede recuperar confirmaciones alejadas, a costa de peor precio o menos espacio útil hasta obstáculos.'),
('continuation_maximum_breakout_wick_ratio','Mecha máxima Continuación','Limita la mecha de rechazo direccional de la vela de ruptura H1.','Subirla admite rupturas con más rechazo; bajarla exige una ruptura más limpia y puede reducir la frecuencia.'),
('qm_max_entry_distance_atr','Distancia Quasimodo','Limita la distancia de entrada al nivel del escenario QM.','Ampliarla tolera mayor alejamiento del hombro. No altera las distancias Fractal o Continuación.'),
('asset_modes','Modo propio del activo','Sobrescribe la selección habitual: Desactivado, Observación u Operar.','Observación impide todas las órdenes del activo, incluso si M5 o Continuación dicen Operar. Heredar elimina la excepción.'),
('m5_symbol_modes','M5 por activo','Sobrescribe exclusivamente el modo general M5 de cada instrumento.','Permite extender M5 a un grupo pequeño conservando el resto en observación. Comparar por episodio para evitar contar dos veces la oportunidad.'),
('continuation_symbol_modes','Continuación por activo','Sobrescribe exclusivamente el modo general Continuación.','Permite observar o desactivar Continuación en un instrumento sin apagar el Fractal ni QM.'),
('research_min_frequency_ratio','Frecuencia mínima comparada','Define la proporción mínima de entradas frente a la base en el replay.','100% evita aprobar una variante con menos entradas; más de 100% exigiría crecimiento. No es un filtro de órdenes en vivo.'),
('research_min_resolved_trades','Muestra mínima comparada','Exige resultados resueltos en ambas variantes para evaluar una comparación.','Subirla evita decidir con muestras diminutas, pero no asegura significación estadística. No limita las entradas en vivo.'),
('research_min_win_rate_improvement_pp','Mejora mínima de WinRate','Exige que el WinRate candidato supere al de la base por estos puntos porcentuales.','1 punto significa pasar, por ejemplo, de 40% a por lo menos 41%. Se evalúa junto a frecuencia y beneficio; no activa variantes automáticamente.'),
('continuation_min_body_ratio','Cuerpo Continuación H1','Exige cuerpo mínimo a las rupturas de Continuación y escenarios que comparten ese requisito.','Bajarlo amplía los quiebres aceptados; subirlo descarta cuerpos pequeños. Cambia también algunas variantes A/V, SBR/RBS y Open–Close.'),
('continuation_min_adx','ADX Continuación H1','Exige un mínimo de ADX en la estructura H1. ADX mide intensidad, no dirección.','Bajarlo admite estructuras menos tendenciales; subirlo reduce entradas. Su utilidad debe comprobarse en cada instrumento.'),
('continuation_fresh_only','Exigir Fresh en Continuación','Exige niveles sin contacto previo según la política Fresh.','Desactivarlo admite niveles no Fresh, pero mantiene el bloqueo de niveles consumidos y la exigencia de primer retest del episodio.'),
('enable_setup_diagnostics','Diagnóstico de rechazo H1','Registra por qué un Fractal u otro setup no pasó sus requisitos.','Ayuda a elegir el filtro responsable de la pérdida de frecuencia; no mejora por sí mismo las entradas.'),
('enable_structure_cache','Reutilizar estructura H1','Reutiliza estructura calculada mientras no cambien velas relevantes ni ajustes.','Reduce trabajo repetido. No permite usar información futura ni reutilizar una estructura tras cambiar sus controles.'),
('prioritize_pending_retests','Priorizar retests pendientes','Analiza antes los setups vivos dentro de cada grupo de ejecución u observación.','Puede reducir oportunidades perdidas por demora del escaneo; no flexibiliza la confirmación.'),
('analysis_outside_entry_lock','Separar análisis y envío','Permite analizar mientras el bloqueo de envío de órdenes está ocupado.','Reduce demoras del análisis; el envío mantiene su bloqueo y validaciones.'),
('av_entry_mode','Modo A/V ampliado','Añade niveles de giro A/V según la definición seleccionada.','Operar habilita este escenario y Observación registra alternativas. Mantiene cuerpo, ADX, mecha, Fresh y retest.'),
('av_entry_definition','Definición A/V','Elige envolvente o giro de cuerpos para las variantes A/V y cambio de función.','Giro de cuerpos puede formar más niveles que envolvente; cambiarlo modifica el patrón y requiere comparación nueva.'),
('role_flip_mode','Modo cambio de función','Admite un nuevo episodio cuando soporte pasa a resistencia o viceversa tras ruptura cerrada.','Recupera oportunidades de reutilización estructural sin aceptar un segundo toque del mismo episodio.'),
('role_flip_max_changes','Cambios máximos de función','Limita cuántos cambios estructurales se admiten por nivel.','Subirlo admite más reutilizaciones y mayor riesgo de desgaste. Cada episodio sigue necesitando ruptura y primer retest.'),
('role_flip_min_displacement_atr','Desplazamiento cambio de función','Exige una separación mínima de la ruptura para renovar el nivel.','Bajarlo acepta cambios menos pronunciados; subirlo filtra rupturas pequeñas.'),
('qm_extended_mode','Modo QM ampliado','Busca hombro, cabeza y neckline entre una ventana más amplia de swings confirmados.','Añade configuraciones QM que no son consecutivas. Conserva ruptura, invalidación de cabeza y retest del hombro.'),
('qm_extended_swing_window','Ventana de swings QM','Controla cuántos swings confirmados examina QM ampliado.','Ampliarla permite estructuras con más swings intermedios; puede añadir patrones más antiguos.'),
('qm_extended_min_head_depth_atr','Profundidad de cabeza QM','Exige una profundidad mínima del barrido respecto al hombro.','Bajarla admite barridos pequeños; subirla puede excluir patrones poco definidos y reducir trades.'),
('macro_structure_mode','Modo dirección macro','Desactivado usa color D1; Observación compara; Operar usa pivotes y rupturas confirmadas.','Afecta activos cuyo filtro macro es obligatorio. Si la estructura queda neutral, espera; no reactiva D1 en sintéticos con veto desactivado.'),
('macro_bias_method','Método macro','Elige estructura D1, H4 o confluencia D1/H4.','H4 responde a otro horizonte; confluencia puede filtrar más entradas. No equivale a desactivar el filtro direccional.'),
('macro_pivot_radius','Confirmación de pivotes','Exige esta cantidad de velas a cada lado del pivote antes de usarlo.','Bajarla confirma antes con swings menores; subirla añade demora y estructura más amplia. Nunca usa pivotes aún sin confirmar.'),
('gap_mode','Modo Open–Close','Habilita niveles de separación entre cuerpos y su retorno confirmado.','Añade un escenario; Operar permite ejecución y Observación mide. Sin tick o spread verificable no forma esa variante.'),
('gap_timeframe','Marco Open–Close','Define si el nivel se forma en H1 o H4.','H4 requiere sus propias velas cerradas y usa otra escala estructural; no es una simple multiplicación de frecuencia.'),
('gap_min_size_atr','Separación Open–Close en ATR','Define uno de los tres mínimos de separación de la banda.','Bajarla solo tendrá efecto si no dominan los mínimos de ticks o spread. El motor usa el mayor de los tres.'),
('gap_min_ticks','Separación Open–Close en ticks','Descarta bandas menores a esta cantidad de ticks del instrumento.','Bajarla admite bandas más pequeñas si también pasan ATR y spread; subirla puede eliminar microseparaciones.'),
('gap_min_spread_multiple','Separación Open–Close respecto al spread','Exige una banda suficientemente grande respecto al coste de entrada observado.','Bajarla admite separaciones con peor relación respecto al spread. No reduce el spread real.'),
('adaptive_history_enabled','Ampliar historial útil','Solicita más velas cuando las cerradas disponibles no alcanzan el mínimo.','Recupera análisis bloqueados por falta de datos; no fabrica historial ni convierte errores en sesgo neutral.'),
('history_min_h1','Mínimo de velas H1','Exige historial suficiente para estructura e indicadores H1.','Subirlo requiere más datos y puede demorar instrumentos nuevos; bajarlo no elimina otros mínimos del cálculo.'),
('history_min_d1','Mínimo de velas D1','Exige suficiente contexto diario para sesgo y obstáculos.','Más velas permiten más contexto; no se deben confundir datos faltantes con permiso para operar.'),
('history_max_request','Límite de consulta histórica','Acota cuántas velas puede solicitar la ampliación adaptativa.','Subirlo puede resolver escasez de historial a costa de latencia. No aumenta la retención disponible del proveedor.'),
('m5_confirmation_mode','Modo M5 general','Añade confirmación M5 dentro del mismo setup H1 y después de su ruptura cerrada.','Puede confirmar antes que M15. Las excepciones por activo prevalecen; se conserva una sola ejecución por episodio.'),
('recovery_window_minutes','Ventana de recuperación','Da tiempo al precio para recuperarse después del primer contacto con el nivel.','Ampliarla admite recuperaciones tardías, dentro de la caducidad total; no autoriza contactos previos a la ruptura.'),
('recovery_min_body_ratio','Cuerpo mínimo de recuperación','Exige cuerpo mínimo a la vela que confirma la recuperación M15 o M5.','Bajarlo admite rebotes débiles; subirlo reduce confirmaciones. Afecta ambos marcos, no solo M5.'),
('h4_neutral_fallback_mode','Alternativa H4 con D1 neutral','Permite comparar o usar H4 solamente cuando el contexto D1 es neutral y el caso es elegible.','Operar puede recuperar entradas macro bloqueadas; Observación no envía esas alternativas. No sustituye errores de datos por permiso.'),
('ai_mode','Modo IA','Desactivado omite IA; Observación registra su puntuación; Filtro aplica una IA compatible.','El filtro solo aporta una selección interpretable si el modelo tiene validación compatible con la estrategia y sus ajustes.'),
('ai_incompatible_policy','IA incompatible','Bloquear impide nuevas entradas; Observar permite evaluar sin el veto del modelo incompatible solo en DEMO.','En Observar DEMO, los umbrales de IA no acreditan ni aseguran la calidad. En cuenta real, esta excepción no autoriza operar.'),
('ai_min_probability','Probabilidad IA general','Fija el umbral general de aceptación de una IA compatible en modo Filtro.','Subirlo reduce candidatos aceptados; bajarlo admite puntuaciones menores. Su efecto debe medirse con calibración independiente.'),
('ai_min_probability_forex','Probabilidad IA Forex y plata','Fija el umbral específico de Forex y plata de la IA compatible.','Tiene prioridad sobre el general en esas categorías; no funciona como filtro de calidad cuando se observa un modelo incompatible.'),
('ai_min_probability_gold','Probabilidad IA oro','Fija el umbral específico de oro de la IA compatible.','Subirlo filtra más señales de oro; no permite trasladar un porcentaje de probabilidad a un WinRate garantizado.'),
('ai_min_probability_volatility','Probabilidad IA Volatility','Fija el umbral específico de Volatility de la IA compatible.','Permite calibrar esta familia por separado; requiere muestras y validación de esa familia.'),
('ai_min_net_expectancy_r','Expectativa mínima IA','Exige expectativa neta mínima estimada por una IA compatible en modo Filtro.','Subirla exige mayor retorno esperado por riesgo, pero una estimación incompatible o mal calibrada no es evidencia de ventaja.'),
('enable_candidate_audit','Registrar candidatos','Persiste episodios, variantes, confirmaciones y motivos de bloqueo.','Permite distinguir lecturas repetidas de oportunidades únicas y analizar qué filtro reduce entradas.'),
('observe_candidate_outcomes','Seguir resultados observados','Evalúa resultados de candidatos sin enviar órdenes.','Permite estudiar alternativas, manteniendo separados resultados observados y operaciones reales.'),
('candidate_outcome_hours','Horizonte observado','Acota la duración de seguimiento de resultados sin órdenes.','Ampliarlo permite observar recorridos más largos; un candidato no resuelto no debe contarse como victoria o pérdida confirmada.'),
('confirmation_tolerance_bars','Tolerancia en velas de confirmación','Permite un margen de velas para validar la confirmación M5 o M15.','Ampliarlo rescata confirmaciones con ligera demora temporal.'),
('confirmation_tolerance_max_atr','Tolerancia en ATR de confirmación','Margen en ATR respecto al nivel de soporte o resistencia durante la confirmación.','Permite absorber mechas sin descartar el setup.'),
('continuation_direct_trigger','Disparo directo en continuación','Habilita la ejecución inmediata en continuación con impulso direccional limpio.','Acelera la entrada sin exigir retesteo prolongado.'),
('enable_fakeout_trap','Trampa de falso quiebre','Detecta barridos de liquidez sobre niveles clave para operar la reversión.','Añade entradas de captura de liquidez en zonas Fresh.'),
('fakeout_min_wick_ratio','Mecha mínima de falso quiebre','Exige una proporción mínima de mecha en la vela de barrido.','Filtra falsos quiebres sin rechazo contundente.'),
('max_fakeout_penetration_atr','Penetración máxima de falso quiebre','Limita cuánto puede penetrar la vela de barrido antes de considerarse ruptura real.','Evita trampas en rupturas que vulneran el nivel estructural.'),
('enable_qmc_pattern','Patrón Quasimodo Continuación','Habilita estructuras QMC a favor del sesgo tendencial.','Aumenta oportunidades válidas en tendencias establecidas.'),
('enable_h1_ema_confluence','Confluencia EMA H1','Comprueba la alineación con la media exponencial H1 antes de autorizar el trade.','Filtra operaciones contrarias a la tendencia de fondo.'),
('enable_m15_micro_stop','Micro Stop Loss M15','Calcula el Stop Loss usando el swing técnico M15 para mejorar el ratio beneficio/riesgo.','Reduce la distancia del stop loss aumentando el potencial R:R.'),
('enable_runner_trailing_lock','Bloqueo Trailing de Runner','Protege la segunda pata dividida asegurando ganancias cuando el precio expande favorablemente.','Permite capturar recorridos largos sin arriesgar el beneficio conseguido.'),
)

GUIDE_HTML = '''<details id="msnrActionGuide"><summary>Guía de cada acción: entradas, calidad y ajustes guardados</summary>
<p class="muted msnr-help">Operar habilita la posibilidad de entrada: la señal aún debe pasar estructura, dirección permitida, obstáculos, riesgo y precio efectivo. Observación registra sin órdenes. Aumentar oportunidades no garantiza mejorar el WinRate; compara las dos cosas junto con beneficio y costes.</p>
<p class="muted msnr-help">Los cuadros históricos de esta página no validan los ajustes actuales ni se recalculan al guardarlos. La IA actual requiere validación compatible; en DEMO con modelo incompatible observado, sus umbrales no están filtrando calidad. Usa el replay actual y separa resultados simulados, observados y ejecutados.</p>
<p class="muted msnr-help">El motor conserva controles adicionales: Step exige su ADX de ejecución (configurable aquí solo para SNR, referencia 25), Boom/Crash comprueban extremos H1 de 24 horas, y la ejecución revisa exposición, posiciones, precio y límites de cartera. Bajar ADX de Continuación o habilitar M5 no elimina esos requisitos. El replay estructural no reproduce todos esos filtros de ejecución.</p>
<p id="msnrGuideProfile" class="muted msnr-help"></p>
<div style="overflow:auto;max-height:520px"><table><thead><tr><th>Acción</th><th>Guardado</th><th>Qué permite</th><th>Qué cambia al ajustarlo</th></tr></thead><tbody id="msnrActionGuideRows"></tbody></table></div>
<p class="muted msnr-help">Proceso: observar una variante → compararla contra la base en las mismas fechas y feed → validar en otro período con costes → decidir su modo por activo. Los criterios de investigación no autorizan órdenes ni promociones automáticas.</p></details>'''

GUIDE_JS = 'const msnrActionGuide='+json.dumps(ACTION_GUIDE,ensure_ascii=False)+';\n'+r'''
function msnrGuideValue(key,value) {
  const mode={off:'Desactivado',shadow:'Observación',live:'Operar',filter:'Filtro compatible',block:'Bloquear',observe:'Observar solo DEMO',body_turns:'Giro de cuerpos',engulfing:'Envolvente',d1_structure:'Estructura D1',h4_structure:'Estructura H4',d1_h4_structure:'Confluencia D1/H4',legacy_utc:'Horario UTC anterior',market_hours:'Horario por mercado'};
  if(typeof value==='boolean') return value?'Activado':'Desactivado';
  if(Array.isArray(value)) return value.join(', ') || 'Sin activos';
  if(value && typeof value==='object') return Object.entries(value).map(([symbol,m])=>symbol+': '+(mode[m] || String(m))).join(' · ') || 'Heredar, sin excepciones';
  if(key==='research_min_win_rate_improvement_pp') return Number(value).toLocaleString('es-CL')+' puntos porcentuales';
  if(key.includes('ratio') || key.startsWith('ai_min_probability')) return Number(value*100).toLocaleString('es-CL')+'%';
  return mode[value] || String(value);
}
function renderMsnrActionGuide(settings) {
  const body=document.getElementById('msnrActionGuideRows');body.replaceChildren();
  for(const [key,label,effect,adjustment] of msnrActionGuide) {
    const row=document.createElement('tr');
    for(const text of [label,msnrGuideValue(key,settings[key]),effect,adjustment]) { const cell=document.createElement('td');cell.textContent=text;row.appendChild(cell); }
    body.appendChild(row);
  }
  const liveM5=Object.entries(settings.m5_symbol_modes || {}).filter(([,mode])=>mode==='live').map(([symbol])=>symbol);
  document.getElementById('msnrGuideProfile').textContent='Guardado v'+settings.version+': Continuación '+msnrGuideValue('continuation_mode',settings.continuation_mode)+'. M5 general: '+msnrGuideValue('m5_confirmation_mode',settings.m5_confirmation_mode)+'. M5 propio en Operar: '+(liveM5.join(', ') || 'ninguno')+'. Comparación: frecuencia mínima '+msnrGuideValue('research_min_frequency_ratio',settings.research_min_frequency_ratio)+', mejora WinRate '+msnrGuideValue('research_min_win_rate_improvement_pp',settings.research_min_win_rate_improvement_pp)+', muestra mínima '+settings.research_min_resolved_trades+' por variante. Estos objetivos no filtran órdenes en vivo.';
}
'''
